@foreach($photoHistory as $photo)<div class="attendance-notice"><b>Selfie check-in: {{ ucfirst($photo->status) }}</b><p>Submitted {{ \Illuminate\Support\Carbon::parse($photo->created_at)->timezone(config('learning.timezone'))->format('M j, g:i A') }}</p>@if($photo->review_note)<p>Teacher: {{ $photo->review_note }}</p>@endif<a href="{{ route('attendance.photos.image',$photo->id) }}" class="font-bold underline" target="_blank" rel="noopener">View my photo</a></div>@endforeach
